package com.marketwatcher.data;

import java.util.List;
import java.util.Locale;
import lombok.Getter;
import lombok.Setter;

import net.runelite.client.util.AsyncBufferedImage;

public class MarketWatcherItem implements Comparable<MarketWatcherItem>
{
	@Getter
	private final AsyncBufferedImage image;

	@Getter
	private final String name;

	@Getter
	private final int itemId;

	@Getter
	@Setter
	private long gePrice;

	// One entry per configured price period, in period order
	@Getter
	private final List<PeriodPrices> periodPrices;

	public MarketWatcherItem(AsyncBufferedImage image, String name, int itemId, long gePrice, List<PeriodPrices> periodPrices)
	{
		this.image = image;
		this.name = name;
		this.itemId = itemId;
		this.gePrice = gePrice;
		this.periodPrices = periodPrices;
	}

	/**
	 * @param filter search text, already trimmed and lowercased; an empty filter matches every item
	 * @return whether this item's name contains the filter, ignoring case
	 */
	public boolean nameMatches(String filter)
	{
		return filter.isEmpty() || name.toLowerCase(Locale.ROOT).contains(filter);
	}

	@Override
	public boolean equals(Object obj)
	{
		if (!(obj instanceof MarketWatcherItem))
		{
			return false;
		}

		final MarketWatcherItem item = (MarketWatcherItem) obj;
		return item.getItemId() == this.itemId;
	}

	@Override
	public int hashCode()
	{
		return Integer.hashCode(itemId);
	}

	@Override
	public int compareTo(MarketWatcherItem other)
	{
		return Long.compare(gePrice, other.getGePrice());
	}
}

