		setLayout(new BorderLayout(5, 0));
		setBorder(new EmptyBorder(5, 0, 5, 0));

		int itemIndex = tab.getItems().indexOf(item);
		int itemsSize = tab.getItems().size();

		JPanel rightPanel = createRightPanel(item, plugin, COMPACT);

