			itemIndex, itemsSize,
			() -> plugin.removeItemFromTab(tab, item),
			() -> plugin.shiftItemInTab(tab, itemIndex, true),
			() -> plugin.shiftItemInTab(tab, itemIndex, false));

		add(rightPanel, BorderLayout.WEST);
		add(actionPanel, BorderLayout.EAST);
